/* Revolut DNA — midnight fintech, aurora gradient accents, borderless */
.theme-revolut-dna {
  --bg: oklch(0.135 0.004 270);
  --surface: oklch(0.205 0.005 270);
  --surface-2: oklch(0.26 0.006 270);
  --fg: oklch(0.97 0.002 270);
  --fg-muted: oklch(0.62 0.006 270);
  --accent: oklch(0.585 0.21 285);
  --accent-fg: oklch(1 0 0);
  --accent-2: oklch(0.75 0.15 160);
  --line: oklch(1 0 0 / 7%);
  --success: oklch(0.75 0.15 160);
  --warning: oklch(0.8 0.14 80);
  --danger: oklch(0.62 0.21 15);
  --radius: 1.125rem;
  --radius-sm: 0.875rem;
  --radius-lg: 1.5rem;
  --radius-pill: 9999px;
  --shadow-1: none;
  --shadow-2: 0 8px 24px oklch(0 0 0 / 35%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 45%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 24px;
  --font-display: "Gantari", "Inter", sans-serif;
  --font-body: "Gantari", "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: -0.02em;
  --label-transform: none;
  --label-tracking: 0.05em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-revolut-dna h1,
.theme-revolut-dna h2,
.theme-revolut-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-revolut-dna { --font-ui: var(--font-body); }
.theme-revolut-dna h1 { font-weight: 700; letter-spacing: -0.03em; }
.theme-revolut-dna h2, .theme-revolut-dna h3 { font-weight: 600; }
.theme-revolut-dna button { border-radius: 9999px; font-weight: 600; border-color: transparent; }
.theme-revolut-dna input, .theme-revolut-dna textarea, .theme-revolut-dna select { border-radius: 9999px; background: var(--surface-2); border-color: transparent; }
.theme-revolut-dna textarea { border-radius: var(--radius-lg); }
/* borderless surfaces: contrast does the work */
.theme-revolut-dna .themed-border { border-color: transparent; }
.theme-revolut-dna th { border-bottom: 1px solid oklch(1 0 0 / 8%); color: var(--fg-muted); font-weight: 500; font-size: 12px; }
.theme-revolut-dna td { border-bottom: 1px solid oklch(1 0 0 / 5%); }
.theme-revolut-dna tbody tr:hover { background: oklch(1 0 0 / 4%); }
/* circular identity fills: avatars and icon chips go periwinkle */
.theme-revolut-dna [class*="rounded-full"][class*="bg-surface"] { background: var(--accent); color: var(--accent-fg); }
.theme-revolut-dna .text-success, .theme-revolut-dna .text-accent { font-weight: 600; }
.theme-revolut-dna ::selection { background: color-mix(in oklab, var(--accent) 35%, transparent); }
.theme-revolut-dna ::-webkit-scrollbar { width: 8px; }
.theme-revolut-dna ::-webkit-scrollbar-thumb { background: oklch(1 0 0 / 18%); border-radius: 999px; }
.theme-revolut-dna .label-caps { text-transform: none; letter-spacing: 0.02em; font-size: 12px; font-weight: 500; }

/* glassy material: sheets, menus and cards frost over what's behind them */
.theme-revolut-dna :is(.bg-card, .bg-popover, [role="dialog"], [role="menu"], [role="listbox"]) {
  background: color-mix(in oklab, var(--surface) 80%, transparent);
  backdrop-filter: blur(24px) saturate(150%);
  -webkit-backdrop-filter: blur(24px) saturate(150%);
}
.theme-revolut-dna .bg-surface, .theme-revolut-dna .bg-surface-2 {
  backdrop-filter: blur(18px) saturate(140%);
  -webkit-backdrop-filter: blur(18px) saturate(140%);
}

/* alt mode: Revolut light — white + iOS gray groups, same periwinkle */
.theme-revolut-dna.alt-mode {
  --bg: oklch(1 0 0);
  --surface: oklch(0.958 0.003 270);
  --surface-2: oklch(0.925 0.004 270);
  --fg: oklch(0.185 0.005 270);
  --fg-muted: oklch(0.52 0.008 270);
  --line: oklch(0 0 0 / 7%);
  --shadow-1: none;
  --shadow-2: 0 8px 24px oklch(0 0 0 / 8%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 12%);
}
.theme-revolut-dna.alt-mode :is(.bg-card, .bg-popover, [role="dialog"], [role="menu"]) {
  background: color-mix(in oklab, var(--surface) 72%, transparent);
}
.theme-revolut-dna.alt-mode th { border-bottom-color: oklch(0 0 0 / 8%); }
.theme-revolut-dna.alt-mode td { border-bottom-color: oklch(0 0 0 / 5%); }
.theme-revolut-dna.alt-mode tbody tr:hover { background: oklch(0 0 0 / 3%); }
.theme-revolut-dna.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0 0 0 / 18%); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-app, var(--font-display));
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-app, var(--font-display)) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
